INSERT INTO `analysismethodstate` (`id`, `projectId`, `selectedMethodId`, `methods`, `trail`) VALUES ('cmugtdrtw001dznwjqxxbie4o','p_2001','sem','[{\"cons\": \"横断面数据难定因果；未纳入调节时可能高估中介。\", \"name\": \"中介效应分析\", \"pros\": \"直接验证H2；可分解直接与间接效应；Bootstrap法稳健。\", \"summary\": \"检验孤独感在社交焦虑与手机依赖间的中介作用，对应H2。\", \"methodId\": \"mediation\", \"checklist\": \"线性关系；残差正态；无多重共线性；Bootstrap5000次；控制变量纳入。\", \"licenseNote\": \"statsmodels + scikit-learn（BSD-3）\", \"recommended\": true, \"prerequisites\": \"社交焦虑、孤独感、手机依赖均为连续变量；样本量512足够；需控制性别、年龄、年级。\", \"robustnessImpact\": \"Bootstrap置信区间不包含0则中介稳健；需报告效应量。\"}, {\"cons\": \"交互项可能共线性；横断面难定因果；需控制混淆变量。\", \"name\": \"调节效应分析\", \"pros\": \"直接验证H3；可绘制简单斜率图；交互项解释直观。\", \"summary\": \"检验自控力负向调节社交焦虑对手机依赖的影响，对应H3。\", \"methodId\": \"moderation\", \"checklist\": \"变量中心化；交互项VIF<5；残差同方差；简单斜率检验。\", \"licenseNote\": \"statsmodels（BSD-3）\", \"recommended\": true, \"prerequisites\": \"自控力为连续变量；需中心化处理；样本量512可检测中小效应。\", \"robustnessImpact\": \"交互项显著且方向为负则调节稳健；需报告ΔR²。\"}, {\"cons\": \"模型易不收敛；调节效应在SEM中实现复杂；需大样本。\", \"name\": \"结构方程模型\", \"pros\": \"同时检验多条路径；可处理测量误差；整体拟合评估。\", \"summary\": \"可同时估计中介与调节，但需潜变量或路径设定，模型复杂。\", \"methodId\": \"sem\", \"checklist\": \"正态性；无离群值；拟合指数CFI>0.9；RMSEA<0.08。\", \"licenseNote\": \"semopy（MIT）\", \"recommended\": false, \"prerequisites\": \"需潜变量或多指标；样本量512可接受；模型需理论驱动。\", \"robustnessImpact\": \"拟合指数达标则结论稳健；否则需修正模型。\"}, {\"cons\": \"无法直接检验间接效应；调节需手动构造交互项。\", \"name\": \"层次回归分析\", \"pros\": \"清晰展示ΔR²；可同时检验中介与调节；操作简单。\", \"summary\": \"用于逐步纳入控制变量、主效应、中介与调节，检验增量效应。\", \"methodId\": \"hierarchical\", \"checklist\": \"线性；残差独立；无多重共线性；控制变量编码正确。\", \"licenseNote\": \"statsmodels（BSD-3）\", \"recommended\": false, \"prerequisites\": \"变量连续；需中心化；样本量512满足；控制变量有序/分类需哑变量。\", \"robustnessImpact\": \"ΔR²显著且方向一致则稳健；需报告VIF。\"}, {\"cons\": \"本选题未提供嵌套变量；组数不足时估计不稳；模型复杂。\", \"name\": \"多层线性模型\", \"pros\": \"处理非独立性；可分解组内与组间效应；适合嵌套数据。\", \"summary\": \"若数据按班级或学校嵌套，可处理层次结构，但本选题未明确嵌套。\", \"methodId\": \"multiLevel\", \"checklist\": \"ICC>0.05；组数>30；随机效应显著；模型收敛。\", \"licenseNote\": \"statsmodels MixedLM（BSD-3）\", \"recommended\": false, \"prerequisites\": \"需明确嵌套结构（如学生嵌套于班级）；样本量512需足够组数。\", \"robustnessImpact\": \"若忽略嵌套则标准误低估；需ICC检验。\"}]','{\"operatedAt\": \"2026-09-25T16:18:07.287Z\", \"dataVersion\": \"v1\", \"methodSource\": \"ai\", \"operatorName\": \"我\", \"candidateCount\": 5, \"unselectedCount\": 5}'),('cmugtdrv1002dznwjdueeirg9','p_2002','sem','[{\"cons\": \"对异常值敏感；无法处理潜变量测量误差。\", \"name\": \"分层回归（Hierarchical Regression）\", \"pros\": \"解释直观、可展示每一步的增量贡献，审稿人熟悉。\", \"summary\": \"按理论层次依次纳入控制变量、自变量、交互项，观察 R² 增量与系数显著性。\", \"methodId\": \"hierarchical\", \"checklist\": \"① 缺失值处理 ② 变量中心化 ③ VIF 诊断 ④ 残差正态性\", \"licenseNote\": \"statsmodels（BSD-3）\", \"recommended\": true, \"prerequisites\": \"连续 / 有序因变量；自变量间不存在严重多重共线性（VIF < 5）。\", \"robustnessImpact\": \"配合 Winsorize 与 Bootstrap 可检验结论稳健性。\"}, {\"cons\": \"计算耗时随重抽样次数上升。\", \"name\": \"Bootstrap 中介效应（5000 次重抽样）\", \"pros\": \"不依赖正态假设，间接效应区间估计更稳健。\", \"summary\": \"估计间接效应 ab 的偏差校正置信区间，判断中介是否成立。\", \"methodId\": \"mediation\", \"checklist\": \"① 三步法路径系数 ② Bootstrap 区间不含 0 ③ 中介比例报告\", \"licenseNote\": \"statsmodels + scikit-learn（BSD-3）\", \"recommended\": true, \"prerequisites\": \"样本量 ≥ 200；自变量、中介、因变量均为连续变量。\", \"robustnessImpact\": \"替换重抽样次数与随机种子检验区间稳定性。\"}, {\"cons\": \"交互项易与主效应共线，需谨慎解释。\", \"name\": \"调节效应（交互项回归）\", \"pros\": \"可直接回答「何时更强 / 更弱」的研究问题。\", \"summary\": \"纳入自变量 × 调节变量交互项，检验调节变量对关系强度的影响。\", \"methodId\": \"moderation\", \"checklist\": \"① 中心化 ② 交互项显著性 ③ 简单斜率图\", \"licenseNote\": \"statsmodels（BSD-3）\", \"recommended\": false, \"prerequisites\": \"调节变量为连续或分类；需对连续变量中心化。\", \"robustnessImpact\": \"简单斜率分析 + Johnson-Neyman 区间。\"}, {\"cons\": \"对样本量与模型设定敏感，收敛问题较多。\", \"name\": \"结构方程模型（SEM）\", \"pros\": \"可校正测量误差，模型整体拟合指标丰富。\", \"summary\": \"同时估计测量模型与结构模型，适合含潜变量的复杂假设。\", \"methodId\": \"sem\", \"checklist\": \"① 测量模型拟合 ② 区分效度 ③ 结构路径\", \"licenseNote\": \"semopy（MIT）\", \"recommended\": false, \"prerequisites\": \"每个潜变量 ≥ 3 个指标；样本量 ≥ 300。\", \"robustnessImpact\": \"比较 CFI / RMSEA / SRMR 的稳定性。\"}, {\"cons\": \"模型设定与解释门槛较高。\", \"name\": \"多层线性模型（HLM）\", \"pros\": \"正确处理非独立性，避免标准误低估。\", \"summary\": \"处理嵌套数据（如学生嵌套于班级），估计跨层效应。\", \"methodId\": \"multiLevel\", \"checklist\": \"① 组内相关系数 ICC ② 随机效应 ③ 跨层交互\", \"licenseNote\": \"statsmodels MixedLM（BSD-3）\", \"recommended\": false, \"prerequisites\": \"明确的分层结构与足够的组数（≥ 30 组）。\", \"robustnessImpact\": \"比较随机截距 / 随机斜率模型的拟合差异。\"}]','{\"operatedAt\": \"2026-09-15T10:24:50.449Z\", \"dataVersion\": \"v1\", \"operatorName\": \"陈同学\", \"candidateCount\": 5, \"unselectedCount\": 4}'),('cmugtdrvv003dznwjtr889pb3','p_2003','mediation','[{\"cons\": \"对异常值敏感；无法处理潜变量测量误差。\", \"name\": \"分层回归（Hierarchical Regression）\", \"pros\": \"解释直观、可展示每一步的增量贡献，审稿人熟悉。\", \"summary\": \"按理论层次依次纳入控制变量、自变量、交互项，观察 R² 增量与系数显著性。\", \"methodId\": \"hierarchical\", \"checklist\": \"① 缺失值处理 ② 变量中心化 ③ VIF 诊断 ④ 残差正态性\", \"licenseNote\": \"statsmodels（BSD-3）\", \"recommended\": true, \"prerequisites\": \"连续 / 有序因变量；自变量间不存在严重多重共线性（VIF < 5）。\", \"robustnessImpact\": \"配合 Winsorize 与 Bootstrap 可检验结论稳健性。\"}, {\"cons\": \"计算耗时随重抽样次数上升。\", \"name\": \"Bootstrap 中介效应（5000 次重抽样）\", \"pros\": \"不依赖正态假设，间接效应区间估计更稳健。\", \"summary\": \"估计间接效应 ab 的偏差校正置信区间，判断中介是否成立。\", \"methodId\": \"mediation\", \"checklist\": \"① 三步法路径系数 ② Bootstrap 区间不含 0 ③ 中介比例报告\", \"licenseNote\": \"statsmodels + scikit-learn（BSD-3）\", \"recommended\": true, \"prerequisites\": \"样本量 ≥ 200；自变量、中介、因变量均为连续变量。\", \"robustnessImpact\": \"替换重抽样次数与随机种子检验区间稳定性。\"}, {\"cons\": \"交互项易与主效应共线，需谨慎解释。\", \"name\": \"调节效应（交互项回归）\", \"pros\": \"可直接回答「何时更强 / 更弱」的研究问题。\", \"summary\": \"纳入自变量 × 调节变量交互项，检验调节变量对关系强度的影响。\", \"methodId\": \"moderation\", \"checklist\": \"① 中心化 ② 交互项显著性 ③ 简单斜率图\", \"licenseNote\": \"statsmodels（BSD-3）\", \"recommended\": false, \"prerequisites\": \"调节变量为连续或分类；需对连续变量中心化。\", \"robustnessImpact\": \"简单斜率分析 + Johnson-Neyman 区间。\"}, {\"cons\": \"对样本量与模型设定敏感，收敛问题较多。\", \"name\": \"结构方程模型（SEM）\", \"pros\": \"可校正测量误差，模型整体拟合指标丰富。\", \"summary\": \"同时估计测量模型与结构模型，适合含潜变量的复杂假设。\", \"methodId\": \"sem\", \"checklist\": \"① 测量模型拟合 ② 区分效度 ③ 结构路径\", \"licenseNote\": \"semopy（MIT）\", \"recommended\": false, \"prerequisites\": \"每个潜变量 ≥ 3 个指标；样本量 ≥ 300。\", \"robustnessImpact\": \"比较 CFI / RMSEA / SRMR 的稳定性。\"}, {\"cons\": \"模型设定与解释门槛较高。\", \"name\": \"多层线性模型（HLM）\", \"pros\": \"正确处理非独立性，避免标准误低估。\", \"summary\": \"处理嵌套数据（如学生嵌套于班级），估计跨层效应。\", \"methodId\": \"multiLevel\", \"checklist\": \"① 组内相关系数 ICC ② 随机效应 ③ 跨层交互\", \"licenseNote\": \"statsmodels MixedLM（BSD-3）\", \"recommended\": false, \"prerequisites\": \"明确的分层结构与足够的组数（≥ 30 组）。\", \"robustnessImpact\": \"比较随机截距 / 随机斜率模型的拟合差异。\"}]','{\"operatedAt\": \"2026-09-05T10:24:50.449Z\", \"dataVersion\": \"v1\", \"operatorName\": \"陈同学\", \"candidateCount\": 5, \"unselectedCount\": 4}'),('cmui3oem2000sm7fc4jvttx5b','p_mui3oekoijak','hierarchical','[{\"code\": {\"r\": \"# 分层回归（可复现）\\nlibrary(haven)\\ndf <- read_sav(\\\"survey_social_anxiety.sav\\\")\\nm1 <- lm(phone_dependence ~ social_anxiety, data = df)\\nm2 <- lm(phone_dependence ~ social_anxiety + loneliness + self_control, data = df)\\nsummary(m2); anova(m1, m2)  # ΔR² 与 F 检验\", \"python\": \"# 分层回归（可复现）\\nimport pandas as pd, statsmodels.api as sm\\ndf = pd.read_spss(\\\"survey_social_anxiety.sav\\\")\\nm1 = sm.OLS(df[\\\"phone_dependence\\\"], sm.add_constant(df[[\\\"social_anxiety\\\"]])).fit()\\nm2 = sm.OLS(df[\\\"phone_dependence\\\"], sm.add_constant(df[[\\\"social_anxiety\\\", \\\"loneliness\\\", \\\"self_control\\\"]])).fit()\\nprint(m1.rsquared, m2.rsquared)  # 报告 ΔR² 与各层 β\"}, \"cons\": \"对异常值敏感；无法处理潜变量测量误差。\", \"name\": \"分层回归（Hierarchical Regression）\", \"pros\": \"解释直观、可展示每一步的增量贡献，审稿人熟悉。\", \"summary\": \"按理论层次依次纳入控制变量、自变量、交互项，观察 R² 增量与系数显著性。\", \"methodId\": \"hierarchical\", \"checklist\": \"① 缺失值处理 ② 变量中心化 ③ VIF 诊断 ④ 残差正态性\", \"licenseNote\": \"statsmodels（BSD-3）\", \"recommended\": true, \"prerequisites\": \"连续 / 有序因变量；自变量间不存在严重多重共线性（VIF < 5）。\", \"robustnessImpact\": \"配合 Winsorize 与 Bootstrap 可检验结论稳健性。\"}, {\"code\": {\"r\": \"# Bootstrap 中介效应（5000 次重抽样）\\nlibrary(haven); library(mediation)\\ndf <- read_sav(\\\"survey_social_anxiety.sav\\\")\\nmed.fit <- lm(loneliness ~ social_anxiety, data = df)\\nout.fit <- lm(phone_dependence ~ social_anxiety + loneliness, data = df)\\nres <- mediate(med.fit, out.fit, treat = \\\"social_anxiety\\\", mediator = \\\"loneliness\\\", boot = TRUE, sims = 5000)\\nsummary(res)  # ACME / ADE / 总效应\", \"python\": \"# Bootstrap 中介效应（5000 次重抽样，seed=42）\\nimport numpy as np, pandas as pd, statsmodels.api as sm\\ndf = pd.read_spss(\\\"survey_social_anxiety.sav\\\")\\n\\ndef paths(d):\\n    a = sm.OLS(d[\\\"loneliness\\\"], sm.add_constant(d[[\\\"social_anxiety\\\"]])).fit().params[\\\"social_anxiety\\\"]\\n    b = sm.OLS(d[\\\"phone_dependence\\\"], sm.add_constant(d[[\\\"social_anxiety\\\", \\\"loneliness\\\"]])).fit().params[\\\"loneliness\\\"]\\n    return a * b\\n\\nrng = np.random.default_rng(42)\\nboots = [paths(df.iloc[rng.choice(len(df), len(df), replace=True)]) for _ in range(5000)]\\nprint(paths(df), np.percentile(boots, [2.5, 97.5]))  # 间接效应 ab 及其 95% CI\"}, \"cons\": \"计算耗时随重抽样次数上升。\", \"name\": \"Bootstrap 中介效应（5000 次重抽样）\", \"pros\": \"不依赖正态假设，间接效应区间估计更稳健。\", \"summary\": \"估计间接效应 ab 的偏差校正置信区间，判断中介是否成立。\", \"methodId\": \"mediation\", \"checklist\": \"① 三步法路径系数 ② Bootstrap 区间不含 0 ③ 中介比例报告\", \"licenseNote\": \"statsmodels + scikit-learn（BSD-3）\", \"recommended\": true, \"prerequisites\": \"样本量 ≥ 200；自变量、中介、因变量均为连续变量。\", \"robustnessImpact\": \"替换重抽样次数与随机种子检验区间稳定性。\"}, {\"code\": {\"r\": \"# 调节效应：交互项回归 + 简单斜率\\nlibrary(haven); library(emmeans)\\ndf <- read_sav(\\\"survey_social_anxiety.sav\\\")\\ndf$x_c <- scale(df$social_anxiety, scale = FALSE)\\ndf$w_c <- scale(df$self_control, scale = FALSE)\\nfit <- lm(phone_dependence ~ x_c * w_c, data = df)\\nsummary(fit); emtrends(fit, ~ w_c, var = \\\"x_c\\\")  # 简单斜率\", \"python\": \"# 调节效应：交互项回归（连续变量先中心化）\\nimport pandas as pd, statsmodels.api as sm\\ndf = pd.read_spss(\\\"survey_social_anxiety.sav\\\")\\ndf[\\\"x_c\\\"] = df[\\\"social_anxiety\\\"] - df[\\\"social_anxiety\\\"].mean()\\ndf[\\\"w_c\\\"] = df[\\\"self_control\\\"] - df[\\\"self_control\\\"].mean()\\ndf[\\\"inter\\\"] = df[\\\"x_c\\\"] * df[\\\"w_c\\\"]\\nfit = sm.OLS(df[\\\"phone_dependence\\\"], sm.add_constant(df[[\\\"x_c\\\", \\\"w_c\\\", \\\"inter\\\"]])).fit()\\nprint(fit.params[\\\"inter\\\"], fit.conf_int().loc[\\\"inter\\\"], fit.rsquared)\"}, \"cons\": \"交互项易与主效应共线，需谨慎解释。\", \"name\": \"调节效应（交互项回归）\", \"pros\": \"可直接回答「何时更强 / 更弱」的研究问题。\", \"summary\": \"纳入自变量 × 调节变量交互项，检验调节变量对关系强度的影响。\", \"methodId\": \"moderation\", \"checklist\": \"① 中心化 ② 交互项显著性 ③ 简单斜率图\", \"licenseNote\": \"statsmodels（BSD-3）\", \"recommended\": false, \"prerequisites\": \"调节变量为连续或分类；需对连续变量中心化。\", \"robustnessImpact\": \"简单斜率分析 + Johnson-Neyman 区间。\"}, {\"code\": {\"r\": \"# 结构方程模型（lavaan）\\nlibrary(haven); library(lavaan)\\ndf <- read_sav(\\\"survey_social_anxiety.sav\\\")\\nfit <- sem(\\\"loneliness ~ social_anxiety\\n            phone_dependence ~ social_anxiety + loneliness\\\", data = df)\\nsummary(fit, fit.measures = TRUE, standardized = TRUE)\", \"python\": \"# 结构方程模型（semopy）\\nimport pandas as pd, semopy\\ndf = pd.read_spss(\\\"survey_social_anxiety.sav\\\")\\nmodel = \\\"\\\"\\\"\\nloneliness ~ social_anxiety\\nphone_dependence ~ social_anxiety + loneliness\\n\\\"\\\"\\\"\\nfit = semopy.Model(model).fit(df)\\nprint(semopy.calc_stats(fit).T)  # CFI / RMSEA / SRMR\"}, \"cons\": \"对样本量与模型设定敏感，收敛问题较多。\", \"name\": \"结构方程模型（SEM）\", \"pros\": \"可校正测量误差，模型整体拟合指标丰富。\", \"summary\": \"同时估计测量模型与结构模型，适合含潜变量的复杂假设。\", \"methodId\": \"sem\", \"checklist\": \"① 测量模型拟合 ② 区分效度 ③ 结构路径\", \"licenseNote\": \"semopy（MIT）\", \"recommended\": false, \"prerequisites\": \"每个潜变量 ≥ 3 个指标；样本量 ≥ 300。\", \"robustnessImpact\": \"比较 CFI / RMSEA / SRMR 的稳定性。\"}, {\"code\": {\"r\": \"# 多层线性模型（lme4）\\nlibrary(haven); library(lme4)\\ndf <- read_sav(\\\"survey_social_anxiety.sav\\\")\\nm0 <- lmer(phone_dependence ~ 1 + (1 | class_id), data = df)\\nm1 <- lmer(phone_dependence ~ social_anxiety + self_control + (1 | class_id), data = df)\\nVarCorr(m0); summary(m1)  # 组内相关系数 ICC\", \"python\": \"# 多层线性模型（HLM，处理嵌套数据）\\nimport pandas as pd, statsmodels.api as sm\\ndf = pd.read_spss(\\\"survey_social_anxiety.sav\\\")\\nm0 = sm.MixedLM.from_formula(\\\"phone_dependence ~ 1\\\", groups=\\\"class_id\\\", data=df).fit()\\nm1 = sm.MixedLM.from_formula(\\\"phone_dependence ~ social_anxiety + self_control\\\", groups=\\\"class_id\\\", data=df).fit()\\nprint(m0.cov_re, m1.summary())  # 先看 ICC，再解释固定效应\"}, \"cons\": \"模型设定与解释门槛较高。\", \"name\": \"多层线性模型（HLM）\", \"pros\": \"正确处理非独立性，避免标准误低估。\", \"summary\": \"处理嵌套数据（如学生嵌套于班级），估计跨层效应。\", \"methodId\": \"multiLevel\", \"checklist\": \"① 组内相关系数 ICC ② 随机效应 ③ 跨层交互\", \"licenseNote\": \"statsmodels MixedLM（BSD-3）\", \"recommended\": false, \"prerequisites\": \"明确的分层结构与足够的组数（≥ 30 组）。\", \"robustnessImpact\": \"比较随机截距 / 随机斜率模型的拟合差异。\"}]','{\"operatedAt\": \"2026-09-26T08:00:48.844Z\", \"dataVersion\": \"v1\", \"operatorName\": \"黎同学\", \"candidateCount\": 5, \"unselectedCount\": 4}'),('cmui3p27o001pm7fc59o3v3zt','p_mui3p26y6nh6','hierarchical','[{\"code\": {\"r\": \"# 分层回归（可复现）\\nlibrary(haven)\\ndf <- read_sav(\\\"survey_social_anxiety.sav\\\")\\nm1 <- lm(phone_dependence ~ social_anxiety, data = df)\\nm2 <- lm(phone_dependence ~ social_anxiety + loneliness + self_control, data = df)\\nsummary(m2); anova(m1, m2)  # ΔR² 与 F 检验\", \"python\": \"# 分层回归（可复现）\\nimport pandas as pd, statsmodels.api as sm\\ndf = pd.read_spss(\\\"survey_social_anxiety.sav\\\")\\nm1 = sm.OLS(df[\\\"phone_dependence\\\"], sm.add_constant(df[[\\\"social_anxiety\\\"]])).fit()\\nm2 = sm.OLS(df[\\\"phone_dependence\\\"], sm.add_constant(df[[\\\"social_anxiety\\\", \\\"loneliness\\\", \\\"self_control\\\"]])).fit()\\nprint(m1.rsquared, m2.rsquared)  # 报告 ΔR² 与各层 β\"}, \"cons\": \"对异常值敏感；无法处理潜变量测量误差。\", \"name\": \"分层回归（Hierarchical Regression）\", \"pros\": \"解释直观、可展示每一步的增量贡献，审稿人熟悉。\", \"summary\": \"按理论层次依次纳入控制变量、自变量、交互项，观察 R² 增量与系数显著性。\", \"methodId\": \"hierarchical\", \"checklist\": \"① 缺失值处理 ② 变量中心化 ③ VIF 诊断 ④ 残差正态性\", \"licenseNote\": \"statsmodels（BSD-3）\", \"recommended\": true, \"prerequisites\": \"连续 / 有序因变量；自变量间不存在严重多重共线性（VIF < 5）。\", \"robustnessImpact\": \"配合 Winsorize 与 Bootstrap 可检验结论稳健性。\"}, {\"code\": {\"r\": \"# Bootstrap 中介效应（5000 次重抽样）\\nlibrary(haven); library(mediation)\\ndf <- read_sav(\\\"survey_social_anxiety.sav\\\")\\nmed.fit <- lm(loneliness ~ social_anxiety, data = df)\\nout.fit <- lm(phone_dependence ~ social_anxiety + loneliness, data = df)\\nres <- mediate(med.fit, out.fit, treat = \\\"social_anxiety\\\", mediator = \\\"loneliness\\\", boot = TRUE, sims = 5000)\\nsummary(res)  # ACME / ADE / 总效应\", \"python\": \"# Bootstrap 中介效应（5000 次重抽样，seed=42）\\nimport numpy as np, pandas as pd, statsmodels.api as sm\\ndf = pd.read_spss(\\\"survey_social_anxiety.sav\\\")\\n\\ndef paths(d):\\n    a = sm.OLS(d[\\\"loneliness\\\"], sm.add_constant(d[[\\\"social_anxiety\\\"]])).fit().params[\\\"social_anxiety\\\"]\\n    b = sm.OLS(d[\\\"phone_dependence\\\"], sm.add_constant(d[[\\\"social_anxiety\\\", \\\"loneliness\\\"]])).fit().params[\\\"loneliness\\\"]\\n    return a * b\\n\\nrng = np.random.default_rng(42)\\nboots = [paths(df.iloc[rng.choice(len(df), len(df), replace=True)]) for _ in range(5000)]\\nprint(paths(df), np.percentile(boots, [2.5, 97.5]))  # 间接效应 ab 及其 95% CI\"}, \"cons\": \"计算耗时随重抽样次数上升。\", \"name\": \"Bootstrap 中介效应（5000 次重抽样）\", \"pros\": \"不依赖正态假设，间接效应区间估计更稳健。\", \"summary\": \"估计间接效应 ab 的偏差校正置信区间，判断中介是否成立。\", \"methodId\": \"mediation\", \"checklist\": \"① 三步法路径系数 ② Bootstrap 区间不含 0 ③ 中介比例报告\", \"licenseNote\": \"statsmodels + scikit-learn（BSD-3）\", \"recommended\": true, \"prerequisites\": \"样本量 ≥ 200；自变量、中介、因变量均为连续变量。\", \"robustnessImpact\": \"替换重抽样次数与随机种子检验区间稳定性。\"}, {\"code\": {\"r\": \"# 调节效应：交互项回归 + 简单斜率\\nlibrary(haven); library(emmeans)\\ndf <- read_sav(\\\"survey_social_anxiety.sav\\\")\\ndf$x_c <- scale(df$social_anxiety, scale = FALSE)\\ndf$w_c <- scale(df$self_control, scale = FALSE)\\nfit <- lm(phone_dependence ~ x_c * w_c, data = df)\\nsummary(fit); emtrends(fit, ~ w_c, var = \\\"x_c\\\")  # 简单斜率\", \"python\": \"# 调节效应：交互项回归（连续变量先中心化）\\nimport pandas as pd, statsmodels.api as sm\\ndf = pd.read_spss(\\\"survey_social_anxiety.sav\\\")\\ndf[\\\"x_c\\\"] = df[\\\"social_anxiety\\\"] - df[\\\"social_anxiety\\\"].mean()\\ndf[\\\"w_c\\\"] = df[\\\"self_control\\\"] - df[\\\"self_control\\\"].mean()\\ndf[\\\"inter\\\"] = df[\\\"x_c\\\"] * df[\\\"w_c\\\"]\\nfit = sm.OLS(df[\\\"phone_dependence\\\"], sm.add_constant(df[[\\\"x_c\\\", \\\"w_c\\\", \\\"inter\\\"]])).fit()\\nprint(fit.params[\\\"inter\\\"], fit.conf_int().loc[\\\"inter\\\"], fit.rsquared)\"}, \"cons\": \"交互项易与主效应共线，需谨慎解释。\", \"name\": \"调节效应（交互项回归）\", \"pros\": \"可直接回答「何时更强 / 更弱」的研究问题。\", \"summary\": \"纳入自变量 × 调节变量交互项，检验调节变量对关系强度的影响。\", \"methodId\": \"moderation\", \"checklist\": \"① 中心化 ② 交互项显著性 ③ 简单斜率图\", \"licenseNote\": \"statsmodels（BSD-3）\", \"recommended\": false, \"prerequisites\": \"调节变量为连续或分类；需对连续变量中心化。\", \"robustnessImpact\": \"简单斜率分析 + Johnson-Neyman 区间。\"}, {\"code\": {\"r\": \"# 结构方程模型（lavaan）\\nlibrary(haven); library(lavaan)\\ndf <- read_sav(\\\"survey_social_anxiety.sav\\\")\\nfit <- sem(\\\"loneliness ~ social_anxiety\\n            phone_dependence ~ social_anxiety + loneliness\\\", data = df)\\nsummary(fit, fit.measures = TRUE, standardized = TRUE)\", \"python\": \"# 结构方程模型（semopy）\\nimport pandas as pd, semopy\\ndf = pd.read_spss(\\\"survey_social_anxiety.sav\\\")\\nmodel = \\\"\\\"\\\"\\nloneliness ~ social_anxiety\\nphone_dependence ~ social_anxiety + loneliness\\n\\\"\\\"\\\"\\nfit = semopy.Model(model).fit(df)\\nprint(semopy.calc_stats(fit).T)  # CFI / RMSEA / SRMR\"}, \"cons\": \"对样本量与模型设定敏感，收敛问题较多。\", \"name\": \"结构方程模型（SEM）\", \"pros\": \"可校正测量误差，模型整体拟合指标丰富。\", \"summary\": \"同时估计测量模型与结构模型，适合含潜变量的复杂假设。\", \"methodId\": \"sem\", \"checklist\": \"① 测量模型拟合 ② 区分效度 ③ 结构路径\", \"licenseNote\": \"semopy（MIT）\", \"recommended\": false, \"prerequisites\": \"每个潜变量 ≥ 3 个指标；样本量 ≥ 300。\", \"robustnessImpact\": \"比较 CFI / RMSEA / SRMR 的稳定性。\"}, {\"code\": {\"r\": \"# 多层线性模型（lme4）\\nlibrary(haven); library(lme4)\\ndf <- read_sav(\\\"survey_social_anxiety.sav\\\")\\nm0 <- lmer(phone_dependence ~ 1 + (1 | class_id), data = df)\\nm1 <- lmer(phone_dependence ~ social_anxiety + self_control + (1 | class_id), data = df)\\nVarCorr(m0); summary(m1)  # 组内相关系数 ICC\", \"python\": \"# 多层线性模型（HLM，处理嵌套数据）\\nimport pandas as pd, statsmodels.api as sm\\ndf = pd.read_spss(\\\"survey_social_anxiety.sav\\\")\\nm0 = sm.MixedLM.from_formula(\\\"phone_dependence ~ 1\\\", groups=\\\"class_id\\\", data=df).fit()\\nm1 = sm.MixedLM.from_formula(\\\"phone_dependence ~ social_anxiety + self_control\\\", groups=\\\"class_id\\\", data=df).fit()\\nprint(m0.cov_re, m1.summary())  # 先看 ICC，再解释固定效应\"}, \"cons\": \"模型设定与解释门槛较高。\", \"name\": \"多层线性模型（HLM）\", \"pros\": \"正确处理非独立性，避免标准误低估。\", \"summary\": \"处理嵌套数据（如学生嵌套于班级），估计跨层效应。\", \"methodId\": \"multiLevel\", \"checklist\": \"① 组内相关系数 ICC ② 随机效应 ③ 跨层交互\", \"licenseNote\": \"statsmodels MixedLM（BSD-3）\", \"recommended\": false, \"prerequisites\": \"明确的分层结构与足够的组数（≥ 30 组）。\", \"robustnessImpact\": \"比较随机截距 / 随机斜率模型的拟合差异。\"}]','{\"operatedAt\": \"2026-09-26T08:01:19.450Z\", \"dataVersion\": \"v1\", \"operatorName\": \"黎同学\", \"candidateCount\": 5, \"unselectedCount\": 4}');
