  `methodName` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `finishedAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `sampleSize` int(11) NOT NULL,
  `effects` json NOT NULL,
