INSERT INTO `litpaper` (`id`, `projectId`, `paperId`, `title`, `authors`, `journal`, `year`, `quartile`, `doi`, `doiStatus`, `doiStatusText`, `citedCount`, `abstractText`, `matchReason`, `relevanceScore`, `citable`) VALUES ('cmugtdrtv0015znwjmav2xj48','p_2001','pa_p_2001_1','Problematic smartphone use and social anxiety among Chinese college students: a moderated mediation model','Zhou, L., Wang, Y., & Chen, H.','Computers in Human Behavior',2024,'JCR Q1','10.1016/j.chb.2024.108012','verified','DOI 已核验',87,'本研究以 1,204 名中国大学生为样本，考察手机依赖与社交焦虑的关系，并检验孤独感的中介作用与自控力的调节作用。结果显示，手机依赖显著正向预测社交焦虑，孤独感起到部分中介作用。','与「社交焦虑与手机依赖的关系研究：一个有调节的中介模型」主题相关（相关度 96%）',96,1),('cmugtdrtv0016znwjkv8a1lfn','p_2001','pa_p_2001_2','Loneliness as a mediator between social anxiety and problematic mobile phone use','Elhai, J. D., Levine, J. C., & Hall, B. J.','Journal of Affective Disorders',2023,'JCR Q1','10.1016/j.jad.2023.04.055','verified','DOI 已核验',152,'基于 982 名大学生样本，作者检验了孤独感在社交焦虑与问题性手机使用之间的中介作用，并讨论了对临床干预的启示。','与「社交焦虑与手机依赖的关系研究：一个有调节的中介模型」主题相关（相关度 92%）',92,1),('cmugtdrtv0017znwj4nnavler','p_2001','pa_p_2001_3','Self-control as a moderator of the link between smartphone use and mental health','Kim, S., & Park, J.','Cyberpsychology, Behavior, and Social Networking',2023,'JCR Q2','10.1089/cyber.2023.0112','verified','DOI 已核验',64,'研究探讨自控力对手机使用与心理健康关系的调节作用，发现高自控力个体受到的不利影响显著更小。','与「社交焦虑与手机依赖的关系研究：一个有调节的中介模型」主题相关（相关度 88%）',88,1),('cmugtdrtv0018znwjnnlf38h6','p_2001','pa_p_2001_4','A meta-analysis of the association between smartphone addiction and anxiety','Liu, Q., Zhang, R., & Sun, X.','Frontiers in Psychology',2022,'JCR Q3','10.3389/fpsyg.2022.904512','verified','DOI 已核验',210,'对 43 项研究的元分析显示，手机成瘾与焦虑的总体相关为中等偏强（r = 0.38），并受测量工具与文化背景的调节。','与「社交焦虑与手机依赖的关系研究：一个有调节的中介模型」主题相关（相关度 84%）',84,1),('cmugtdrtv0019znwjn2bif9al','p_2001','pa_p_2001_5','社交焦虑与手机依赖：孤独感的中介与性别的调节','陈某某, 李某某','心理学报',2023,'CSSCI','10.3724/SP.J.1041.2023.00456','verified','DOI 已核验',128,'以 780 名大学生为被试，采用结构方程模型检验孤独感在社交焦虑与手机依赖之间的中介作用，并考察性别差异。','与「社交焦虑与手机依赖的关系研究：一个有调节的中介模型」主题相关（相关度 90%）',90,1),('cmugtdrtv001aznwjdmh15fan','p_2001','pa_p_2001_6','Longitudinal links between social anxiety and problematic phone use during the pandemic','Coyne, S. M., Rogers, A. A., & Zurcher, J. D.','Computers in Human Behavior',2022,'JCR Q1','10.1016/j.chb.2022.107288','verified','DOI 已核验',118,'三波纵向追踪显示，社交焦虑与问题性手机使用存在双向关联，且受社会支持的中介影响。','与「社交焦虑与手机依赖的关系研究：一个有调节的中介模型」主题相关（相关度 83%）',83,1),('cmugtdrv10025znwjxymvencu','p_2002','pa_p_2002_1','Problematic smartphone use and social anxiety among Chinese college students: a moderated mediation model','Zhou, L., Wang, Y., & Chen, H.','Computers in Human Behavior',2024,'JCR Q1','10.1016/j.chb.2024.108012','verified','DOI 已核验',87,'本研究以 1,204 名中国大学生为样本，考察手机依赖与社交焦虑的关系，并检验孤独感的中介作用与自控力的调节作用。结果显示，手机依赖显著正向预测社交焦虑，孤独感起到部分中介作用。','与「短视频使用对大学生睡眠质量的影响：基于 ESM 的实证研究」主题相关（相关度 96%）',96,1),('cmugtdrv10026znwj5zbbmezz','p_2002','pa_p_2002_2','Loneliness as a mediator between social anxiety and problematic mobile phone use','Elhai, J. D., Levine, J. C., & Hall, B. J.','Journal of Affective Disorders',2023,'JCR Q1','10.1016/j.jad.2023.04.055','verified','DOI 已核验',152,'基于 982 名大学生样本，作者检验了孤独感在社交焦虑与问题性手机使用之间的中介作用，并讨论了对临床干预的启示。','与「短视频使用对大学生睡眠质量的影响：基于 ESM 的实证研究」主题相关（相关度 92%）',92,1),('cmugtdrv10027znwjmio9fqnv','p_2002','pa_p_2002_3','Self-control as a moderator of the link between smartphone use and mental health','Kim, S., & Park, J.','Cyberpsychology, Behavior, and Social Networking',2023,'JCR Q2','10.1089/cyber.2023.0112','verified','DOI 已核验',64,'研究探讨自控力对手机使用与心理健康关系的调节作用，发现高自控力个体受到的不利影响显著更小。','与「短视频使用对大学生睡眠质量的影响：基于 ESM 的实证研究」主题相关（相关度 88%）',88,1),('cmugtdrv10028znwj8wq5i06a','p_2002','pa_p_2002_4','A meta-analysis of the association between smartphone addiction and anxiety','Liu, Q., Zhang, R., & Sun, X.','Frontiers in Psychology',2022,'JCR Q3','10.3389/fpsyg.2022.904512','verified','DOI 已核验',210,'对 43 项研究的元分析显示，手机成瘾与焦虑的总体相关为中等偏强（r = 0.38），并受测量工具与文化背景的调节。','与「短视频使用对大学生睡眠质量的影响：基于 ESM 的实证研究」主题相关（相关度 84%）',84,1)