INSERT INTO `reviewstate` (`id`, `projectId`, `data`) VALUES ('cmugtdrtw001hznwjkwg3bdd1','p_2001','{\"field\": \"心理学\", \"issues\": [{\"code\": \"H1\", \"type\": \"hard\", \"title\": \"因果推断过强\", \"handled\": \"none\", \"issueId\": \"r_1\", \"replyable\": true, \"confidence\": \"high\", \"description\": \"横断数据不足以支持「导致」的表述，建议改为「与……相关」。\", \"frequencyText\": \"同类意见在顶刊审稿中出现 47%\", \"confidenceText\": \"置信度：高\"}, {\"code\": \"H2\", \"type\": \"hard\", \"title\": \"共同方法偏差未检验\", \"handled\": \"none\", \"issueId\": \"r_2\", \"replyable\": true, \"confidence\": \"high\", \"description\": \"建议补充 Harman 单因子检验或标记变量法。\", \"frequencyText\": \"同类意见在顶刊审稿中出现 38%\", \"confidenceText\": \"置信度：高\"}, {\"code\": \"D1\", \"type\": \"dispute\", \"title\": \"中介比例的解读存在争议\", \"handled\": \"none\", \"issueId\": \"r_3\", \"replyable\": true, \"confidence\": \"medium\", \"description\": \"中介比例不稳定，建议弱化其解释权重。\", \"frequencyText\": \"同类意见在顶刊审稿中出现 22%\", \"confidenceText\": \"置信度：中\"}, {\"code\": \"S1\", \"type\": \"style\", \"title\": \"摘要字数超出限制\", \"handled\": \"none\", \"issueId\": \"r_4\", \"replyable\": false, \"confidence\": \"low\", \"description\": \"摘要 268 词，建议压缩至 200 词以内。\", \"frequencyText\": \"同类意见在顶刊审稿中出现 15%\", \"confidenceText\": \"置信度：低\"}], \"summary\": {\"ignored\": 0, \"accepted\": 0, \"disputed\": 0, \"corpusCount\": 860}, \"rebuttals\": [{\"steps\": [\"感谢审稿人指出因果推断问题。本研究采用横断面问卷设计，在原文中已明确说明‘本研究为横断面设计，无法确立因果关系’，所有因果表述均基于理论推导，旨在为未来纵向研究提供假设。\", \"我们已在讨论部分补充说明：‘社交焦虑与手机依赖的关系可能为双向，未来需采用交叉滞后设计或实验法进一步验证因果方向。’\", \"作者坚持认为，在理论框架下提出因果假设是合理的，但不应过度解读为已证实的因果关系。\"], \"title\": \"关于因果推断过强的回应\", \"issueCode\": \"H1\"}, {\"steps\": [\"感谢审稿人提醒。我们承认原稿未报告共同方法偏差检验，现已采用Harman单因素检验法对全部问卷项目进行未旋转主成分分析，结果显示第一个因子解释变异量为28.37%，小于40%的临界值，表明共同方法偏差不严重。\", \"此外，我们补充了控制未测量方法因子后的CFA比较，模型拟合无显著改善，进一步支持共同方法偏差未对结果造成实质影响。\", \"作者认为，虽然横断面自我报告数据存在共同方法偏差风险，但现有检验表明该风险在可接受范围内，不影响主要结论的稳健性。\"], \"title\": \"关于共同方法偏差未检验的回应\", \"issueCode\": \"H2\"}, {\"steps\": [\"感谢审稿人指出中介比例解读的争议。我们承认中介效应比例（如ab/c）的解读存在局限性，尤其是在总效应较小时可能不稳定。\", \"我们已在文中补充说明：‘中介效应比例仅作为效应量的辅助描述，不应过度依赖其数值大小，建议结合间接效应的置信区间和效应量指标综合判断。’\", \"作者坚持认为，报告中介比例有助于直观理解中介效应的相对大小，但需谨慎解读，未来研究可考虑采用更稳健的效应量指标（如完全标准化间接效应）。\"], \"title\": \"关于中介比例解读争议的回应\", \"issueCode\": \"D1\"}, {\"steps\": [\"感谢编辑指出摘要字数问题。我们已按照期刊要求将摘要字数压缩至规定范围内（例如250字以内），删减了背景和讨论中的冗余表述，保留核心目的、方法、结果和结论。\", \"修改后的摘要仍完整呈现了研究的关键信息，包括有调节的中介模型的主要发现。\", \"作者确认摘要字数已符合期刊要求，并感谢编辑的细致提醒。\"], \"title\": \"关于摘要字数超出限制的回应\", \"issueCode\": \"S1\"}], \"disclaimer\": \"模拟评审基于发表于顶刊的审稿意见语料，仅作写作参考，不代表真实审稿结论。\", \"calibration\": {\"note\": \"基于 860 篇顶刊已发表论文的审稿意见语料校准。\", \"paperCount\": 1200, \"corpusCount\": 860, \"calibratedAt\": \"2026-09-25T10:24:50.452Z\"}, \"reviewTarget\": \"社交焦虑与手机依赖的关系研究：一个有调节的中介模型\", \"revisionPaths\": [{\"text\": \"将「导致」改为「与……相关」，并在局限部分说明因果方向的限制。\", \"title\": \"修改建议\", \"issueCode\": \"H1\"}, {\"text\": \"在方法部分补充共同方法偏差检验，并报告结果。\", \"title\": \"修改建议\", \"issueCode\": \"H2\"}, {\"text\": \"中介比例不稳定，建议弱化其解释权重。 争议类问题可以保留你的主张：正文弱化强表述，回复信中给出依据、边界条件与备选解释。\", \"title\": \"修改建议（中介比例的解读存在争议）\", \"issueCode\": \"D1\"}, {\"text\": \"摘要 268 词，建议压缩至 200 词以内。 表达与结构问题只需按目标期刊的格式要求调整篇幅与措辞，不改动研究结论与数据。\", \"title\": \"修改建议（摘要字数超出限制）\", \"issueCode\": \"S1\"}], \"targetJournal\": \"Computers in Human Behavior\"}'),('cmugtdrv2002hznwj21h8d4ea','p_2002','{\"field\": \"心理学\", \"issues\": [{\"code\": \"H1\", \"type\": \"hard\", \"title\": \"因果推断过强\", \"handled\": \"none\", \"issueId\": \"r_1\", \"replyable\": true, \"confidence\": \"high\", \"description\": \"横断数据不足以支持「导致」的表述，建议改为「与……相关」。\", \"frequencyText\": \"同类意见在顶刊审稿中出现 47%\", \"confidenceText\": \"置信度：高\"}, {\"code\": \"H2\", \"type\": \"hard\", \"title\": \"共同方法偏差未检验\", \"handled\": \"none\", \"issueId\": \"r_2\", \"replyable\": true, \"confidence\": \"high\", \"description\": \"建议补充 Harman 单因子检验或标记变量法。\", \"frequencyText\": \"同类意见在顶刊审稿中出现 38%\", \"confidenceText\": \"置信度：高\"}, {\"code\": \"D1\", \"type\": \"dispute\", \"title\": \"中介比例的解读存在争议\", \"handled\": \"none\", \"issueId\": \"r_3\", \"replyable\": true, \"confidence\": \"medium\", \"description\": \"中介比例不稳定，建议弱化其解释权重。\", \"frequencyText\": \"同类意见在顶刊审稿中出现 22%\", \"confidenceText\": \"置信度：中\"}, {\"code\": \"S1\", \"type\": \"style\", \"title\": \"摘要字数超出限制\", \"handled\": \"none\", \"issueId\": \"r_4\", \"replyable\": false, \"confidence\": \"low\", \"description\": \"摘要 268 词，建议压缩至 200 词以内。\", \"frequencyText\": \"同类意见在顶刊审稿中出现 15%\", \"confidenceText\": \"置信度：低\"}], \"summary\": {\"ignored\": 0, \"accepted\": 0, \"disputed\": 0, \"corpusCount\": 860}, \"rebuttals\": [{\"steps\": [\"感谢审稿人指出因果表述问题。\", \"我们已在正文中统一改为相关性表述。\", \"并在局限部分补充了纵向设计的未来方向。\"], \"title\": \"回复草稿\", \"issueCode\": \"H1\"}], \"disclaimer\": \"模拟评审基于发表于顶刊的审稿意见语料，仅作写作参考，不代表真实审稿结论。\", \"calibration\": {\"note\": \"基于 860 篇顶刊已发表论文的审稿意见语料校准。\", \"paperCount\": 1200, \"corpusCount\": 860, \"calibratedAt\": \"2026-09-25T10:24:50.494Z\"}, \"reviewTarget\": \"短视频使用对大学生睡眠质量的影响：基于 ESM 的实证研究\", \"revisionPaths\": [{\"text\": \"将「导致」改为「与……相关」，并在局限部分说明因果方向的限制。\", \"title\": \"修改建议\", \"issueCode\": \"H1\"}, {\"text\": \"在方法部分补充共同方法偏差检验，并报告结果。\", \"title\": \"修改建议\", \"issueCode\": \"H2\"}], \"targetJournal\": \"Computers in Human Behavior\"}'),('cmugtdrvw003hznwj384hrgw3','p_2003','{\"field\": \"教育学\", \"issues\": [{\"code\": \"H1\", \"type\": \"hard\", \"title\": \"因果推断过强\", \"handled\": \"none\", \"issueId\": \"r_1\", \"replyable\": true, \"confidence\": \"high\", \"description\": \"横断数据不足以支持「导致」的表述，建议改为「与……相关」。\", \"frequencyText\": \"同类意见在顶刊审稿中出现 47%\", \"confidenceText\": \"置信度：高\"}, {\"code\": \"H2\", \"type\": \"hard\", \"title\": \"共同方法偏差未检验\", \"handled\": \"none\", \"issueId\": \"r_2\", \"replyable\": true, \"confidence\": \"high\", \"description\": \"建议补充 Harman 单因子检验或标记变量法。\", \"frequencyText\": \"同类意见在顶刊审稿中出现 38%\", \"confidenceText\": \"置信度：高\"}, {\"code\": \"D1\", \"type\": \"dispute\", \"title\": \"中介比例的解读存在争议\", \"handled\": \"none\", \"issueId\": \"r_3\", \"replyable\": true, \"confidence\": \"medium\", \"description\": \"中介比例不稳定，建议弱化其解释权重。\", \"frequencyText\": \"同类意见在顶刊