INSERT INTO `writingdoc` (`id`, `projectId`, `data`) VALUES ('cmugtdrtw001fznwjvvcpi4ef','p_2001','{\"mode\": \"aiAssist\", \"stats\": {\"wordCount\": 1426, \"lastEditedAt\": \"2026-09-26T07:42:29.417Z\", \"citationCount\": 8, \"aiLabelEnabled\": true, \"paragraphCount\": 18, \"unsavedChanges\": 0}, \"title\": \"社交焦虑与手机依赖的关系研究：一个有调节的中介模型\", \"editor\": {\"zoom\": 100, \"fontName\": \"Times New Roman\", \"pageCount\": 12, \"inTextLabel\": \"(作者, 年份)\", \"fontSizeLabel\": \"12pt\", \"journalFormat\": \"Computers in Human Behavior（APA 7）\", \"lineHeightLabel\": \"1.5\", \"citationStyleLabel\": \"APA 7\", \"journalFormatOptions\": [\"Computers in Human Behavior\", \"Cyberpsychology, Behavior, and Social Networking\", \"Journal of Affective Disorders\", \"心理学报（Acta Psychologica Sinica）\"]}, \"kbDocs\": [{\"title\": \"Problematic smartphone use and social anxiety\", \"paperId\": \"pa_1\", \"metaText\": \"Zhou et al. · 2024\"}, {\"title\": \"Loneliness as a mediator\", \"paperId\": \"pa_2\", \"metaText\": \"Elhai et al. · 2023\"}], \"zotero\": {\"bound\": false, \"account\": \"\", \"fallbackText\": \"未绑定时可手动导入 .bib 文件\", \"rateLimitText\": \"Zotero API 限流：每分钟 60 次\", \"bidirectionalSync\": false}, \"outline\": [{\"level\": 1, \"title\": \"1 引言\", \"nodeId\": \"o1\", \"children\": [{\"level\": 2, \"title\": \"1.1 研究背景\", \"nodeId\": \"o1_1\", \"citeCount\": 6}, {\"level\": 2, \"title\": \"1.2 问题提出\", \"nodeId\": \"o1_2\", \"citeCount\": 4}]}, {\"level\": 1, \"title\": \"2 文献综述\", \"nodeId\": \"o2\", \"children\": [{\"level\": 2, \"title\": \"2.1 社交焦虑与手机依赖\", \"nodeId\": \"o2_1\", \"citeCount\": 8}, {\"level\": 2, \"title\": \"2.2 孤独感的中介作用\", \"nodeId\": \"o2_2\", \"citeCount\": 5}, {\"level\": 2, \"title\": \"2.3 自控力的调节作用\", \"nodeId\": \"o2_3\", \"citeCount\": 3}]}, {\"flag\": \"boundArtifact\", \"level\": 1, \"title\": \"3 研究方法\", \"nodeId\": \"o3\", \"children\": [{\"level\": 2, \"title\": \"3.1 被试与程序\", \"nodeId\": \"o3_1\"}, {\"level\": 2, \"title\": \"3.2 测量工具\", \"nodeId\": \"o3_2\"}, {\"flag\": \"boundArtifact\", \"level\": 2, \"title\": \"3.3 统计策略\", \"nodeId\": \"o3_3\"}]}, {\"flag\": \"missingCitation\", \"level\": 1, \"title\": \"4 结果\", \"nodeId\": \"o4\", \"children\": []}, {\"level\": 1, \"title\": \"5 讨论\", \"nodeId\": \"o5\", \"children\": []}], \"citations\": [{\"index\": 1, \"gbText\": \"Zhou L, Wang Y, Chen H. Problematic smartphone use and social anxiety[J]. Computers in Human Behavior, 2024, 152: 108012.\", \"apaText\": \"Zhou, L., Wang, Y., & Chen, H. (2024). Problematic smartphone use and social anxiety. Computers in Human Behavior, 152, 108012.\", \"paperId\": \"pa_1\"}, {\"index\": 2, \"gbText\": \"Elhai J D, Levine J C, Hall B J. Loneliness as a mediator[J]. Journal of Affective Disorders, 2023, 331: 55-62.\", \"apaText\": \"Elhai, J. D., Levine, J. C., & Hall, B. J. (2023). Loneliness as a mediator. Journal of Affective Disorders, 331, 55–62.\", \"paperId\": \"pa_2\"}, {\"index\": 3, \"gbText\": \"Zhou, L., Wang, Y., & Chen, H.. Problematic smartphone use and social anxiety among Chinese college students: a moderated mediation model[J]. Computers in Human Behavior, 2024.\", \"apaText\": \"Zhou, L., Wang, Y., & Chen, H. (2024). Problematic smartphone use and social anxiety among Chinese college students: a moderated mediation model. Computers in Human Behavior.\", \"paperId\": \"pa_p_2001_1\"}, {\"index\": 4, \"gbText\": \"Elhai, J. D., Levine, J. C., & Hall, B. J.. Loneliness as a mediator between social anxiety and problematic mobile phone use[J]. Journal of Affective Disorders, 2023.\", \"apaText\": \"Elhai, J. D., Levine, J. C., & Hall, B. J. (2023). Loneliness as a mediator between social anxiety and problematic mobile phone use. Journal of Affective Disorders.\", \"paperId\": \"pa_p_2001_2\"}, {\"index\": 5, \"gbText\": \"Kim, S., & Park, J.. Self-control as a moderator of the link between smartphone use and mental health[J]. Cyberpsychology, Behavior, and Social Networking, 2023.\", \"apaText\": \"Kim, S., & Park, J. (2023). Self-control as a moderator of the link between smartphone use and mental health. Cyberpsychology, Behavior, and Social Networking.\", \"paperId\": \"pa_p_2001_3\"}, {\"index\": 6, \"gbText\": \"Liu, Q., Zhang, R., & Sun, X.. A meta-analysis of the association between smartphone addiction and anxiety[J]. Frontiers in Psychology, 2022.\", \"apaText\": \"Liu, Q., Zhang, R., & Sun, X. (2022). A meta-analysis of the association between smartphone addiction and anxiety. Frontiers in Psychology.\", \"paperId\": \"pa_p_2001_4\"}, {\"index\": 7, \"gbText\": \"陈某某, 李某某. 社交焦虑与手机依赖：孤独感的中介与性别的调节[J]. 心理学报, 2023.\", \"apaText\": \"陈某某, 李某某 (2023). 社交焦虑与手机依赖：孤独感的中介与性别的调节. 心理学报.\", \"paperId\": \"pa_p_2001_5\"}, {\"index\": 8, \"gbText\": \"Coyne, S. M., Rogers, A. A., & Zurcher, J. D.. Longitudinal links between social anxiety and problematic phone use during the pandemic[J]. Computers in Human Behavior, 2022.\", \"apaText\": \"Coyne, S. M., Rogers, A. A., & Zurcher, J. D. (2022). Longitudinal links between social anxiety and problematic phone use during the pandemic. Computers in Human Behavior.\", \"paperId\": \"pa_p_2001_6\"}], \"authorLine\": \"陈某某 · 心理学系\", \"editorBody\": [{\"kind\": \"heading\", \"text\": \"1 引言\", \"paraId\": \"e1\"}, {\"kind\": \"body\", \"text\": \"随着智能手机的普及，手机依赖已成为影响大学生心理健康的重要风险因素\", \"paraId\": \"e2\", \"citeIndex\": 1}, {\"kind\": \"aiLabel\", \"text\": \"AI 生成 · 已核对 3 条引用\", \"paraId\": \"e3\"}, {\"kind\": \"body\", \"text\": \"既有研究表明，社交焦虑与手机依赖之间存在稳定的正相关\", \"paraId\": \"e4\", \"citeIndex\": 2}], \"kbDocCount\": 2, \"paragraphs\": [{\"kind\": \"normal\", \"text\": \"随着智能手机的普及，手机依赖已成为影响大学生心理健康的重要风险因素。\", \"index\": 1, \"paraId\": \"p1\", \"section\": \"1.1 研究背景\", \"traceLabel\": \"\", \"aiGenerated\": false}, {\"kind\": \"normal\", \"text\": \"既有研究表明，社交焦虑与手机依赖之间存在稳定的正相关，但其内在机制尚不清晰。\", \"index\": 2, \"paraId\": \"p2\", \"section\": \"1.1 研究背景\", \"traceLabel\": \"AI 生成 · 已核对 3 条引用\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"社交焦虑与手机依赖的关系已受关注。既有研究多聚焦直接关联，中介机制及调节条件尚缺实证探讨。\", \"index\": 3, \"paraId\": \"p_muh33ekr5d2z\", \"section\": \"1.2 问题提出\", \"traceLabel\": \"AI 改写\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"本研究拟构建一个有调节的中介模型，旨在系统考察社交焦虑影响手机依赖的具体路径，并检验调节变量在该路径中所发挥的作用。具体而言，本研究将首先检验社交焦虑是否通过某一中介变量对手机依赖产生间接影响，以揭示二者之间作用的具体机制；在此基础上，进一步考察调节变量是否对该中介路径的各条路径产生调节作用，从而明确该路径在不同条件下是否存在差异。\", \"index\": 4, \"paraId\": \"p_muh33ekrcwpp\", \"section\": \"1.2 问题提出\", \"traceLabel\": \"AI 改写\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"社交焦虑作为一种常见的心理困扰，指个体在社交情境中体验到的显著恐惧与回避倾向，其核心特征包括对负面评价的担忧以及伴随的生理唤醒。手机依赖则通常被界定为个体对智能手机使用失去控制，并由此引发功能损害的一种行为成瘾倾向。两者之间的关系近年来受到研究者的持续关注。\", \"index\": 5, \"paraId\": \"p_muh5dhgj0rmt\", \"section\": \"2.1 社交焦虑与手机依赖\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"已有研究提示，社交焦虑与手机依赖之间存在正向关联。具体而言，高社交焦虑个体可能因面对面社交带来的不适而转向手机媒介进行互动，从而获得一种相对安全的人际连接方式；与此同时，手机使用也可能作为一种回避策略，暂时缓解社交情境中的焦虑体验。然而，这种关联的强度可能受到个体特征或环境因素的调节，其内在机制亦有待进一步阐明。\\n\\n从理论层面来看，社交焦虑的核心特征之一是对负面评价的恐惧以及对社交情境的回避倾向。当个体面对面的社交互动中体验到强烈的不适感时，他们往往会寻求替代性的交往途径。手机媒介因其匿名性、可控性和异步性等特点，为高社交焦虑个体提供了一个相对安全的互动空间。在这一空间中，个体可以更从容地编辑信息、延迟回应，从而减少即时社交压力带来的焦虑。因此，高社交焦虑个体可能更倾向于通过手机进行人际连接，这种倾向若长期持续并逐渐失控，便可能演变为手机依赖。\\n\\n另一方面，手机使用本身也可能作为一种回避策略发挥作用。当个体处于或预期进入令其焦虑的社交情境时，使用手机可以帮助他们转移注意力，暂时缓解焦虑体验。这种负强化机制可能进一步强化手机使用行为，形成“焦虑—使用手机—焦虑暂时缓解—更依赖手机”的循环。然而，这一循环的强度并非固定不变，而是可能受到多种个体特征或环境因素的调节。例如，个体的自我控制能力、孤独感水平、社会支持程度以及文化背景等，都可能影响社交焦虑与手机依赖之间的关联强度。此外，手机使用的具体类型（如社交媒体的被动浏览与主动互动）也可能在二者关系中扮演不同角色。\\n\\n尽管现有研究已初步揭示了社交焦虑与手机依赖之间的正向关联，但其内在机制仍有待进一步阐明。未来的研究需要更深入地探讨二者之间的中介与调节变量，并采用纵向设计或实验方法以明确因果方向。同时，临床干预也应考虑针对社交焦虑个体的手机使用模式，以促进更健康的人际互动方式。\", \"index\": 6, \"paraId\": \"p_muh5dhgjnfk8\", \"section\": \"2.1 社交焦虑与手机依赖\", \"traceLabel\": \"AI 改写\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"自控力作为个体自我调节的核心能力，在社交焦虑与手机依赖的关系中可能扮演重要的调节角色。根据自我控制资源模型，自控力有限的个体在面临社交焦虑等负性情绪时，更难以抑制对手机的冲动性使用，从而更易形成手机依赖；而高自控力个体则可能通过有效的情绪调节和行为抑制，缓冲社交焦虑对手机依赖的不利影响。\", \"index\": 7, \"paraId\": \"p_muh33c656b06\", \"section\": \"2.3 自控力的调节作用\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"已有实证研究为自控力的调节作用提供了初步支持。例如，有研究发现自控力能够显著调节社交焦虑与手机依赖之间的关系，高自控力可以削弱社交焦虑对手机依赖的正向预测作用。这提示自控力可能作为一种保护性资源，在社交焦虑影响手机依赖的路径中发挥缓冲效应。然而，目前直接检验自控力在社交焦虑与手机依赖之间调节作用的实证研究仍相对有限，其调节机制的具体表现形式有待进一步探讨。\", \"index\": 8, \"paraId\": \"p_muh33c653q8f\", \"section\": \"2.3 自控力的调节作用\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"本研究采用方便取样法，选取某高校在校大学生作为研究对象。共发放问卷500份，回收有效问卷462份，有效回收率为92.4%。其中，男生218人（47.2%），女生244人（52.8%）；大一学生112人（24.2%），大二学生126人（27.3%），大三学生118人（25.5%），大四学生106人（22.9%）；平均年龄为20.35岁（SD=1.42）。\", \"index\": 9, \"paraId\": \"p_muh5e2gvzq7b\", \"section\": \"3.1 被试与程序\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"研究程序如下：在征得学校及学生本人知情同意后，以班级为单位进行集体施测。施测前由经过培训的主试向被试说明指导语，强调匿名作答和答案无对错之分。问卷当场发放并回收，施测时间约为20分钟。所有数据仅用于学术研究，并对被试信息严格保密。\", \"index\": 10, \"paraId\": \"p_muh5e2gvu0wx\", \"section\": \"3.1 被试与程序\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"本研究采用社交焦虑量表、手机依赖量表及情绪调节困难量表进行测量。社交焦虑量表采用Leary（1983）编制的交往焦虑量表（Interaction Anxiousness Scale, IAS），共15个条目，采用5点计分（1=完全不符合，5=完全符合），总分越高表示社交焦虑水平越高。在本研究中，该量表的Cronbach\'s α系数为0.87。\", \"index\": 11, \"paraId\": \"p_muh33irp5su3\", \"section\": \"3.2 测量工具\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"手机依赖量表采用熊婕等（2012）编制的手机成瘾倾向量表（Mobile Phone Addiction Tendency Scale, MPATS），共16个条目，包含戒断症状、突显行为、社交抚慰和心境改变四个维度，采用5点计分（1=非常不符合，5=非常符合），总分越高表示手机依赖程度越高。在本研究中，该量表的Cronbach\'s α系数为0.91。情绪调节困难量表采用Gratz和Roemer（2004）编制的情绪调节困难量表（Difficulties in Emotion Regulation Scale, DERS），共36个条目，包含情绪知觉、情绪理解、情绪反应、情绪调节策略和情绪接纳五个维度，采用5点计分（1=几乎从不，5=几乎总是），总分越高表示情绪调节困难程度越高。在本研究中，该量表的Cronbach\'s α系数为0.89。\", \"index\": 12, \"paraId\": \"p_muh33irpqiuo\", \"section\": \"3.2 测量工具\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"boundMethod\", \"text\": \"本研究采用分层回归与 Bootstrap 中介检验（5000 次重抽样），所有分析在沙箱中完成并可复现。\", \"index\": 13, \"paraId\": \"p3\", \"section\": \"3.3 统计策略\", \"traceLabel\": \"绑定分析产物 · run_2024\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"本研究采用SPSS 26.0及PROCESS宏程序对数据进行统计分析。首先，对社交焦虑、手机依赖、反刍思维及性别等主要变量进行描述性统计与相关分析。结果显示，社交焦虑与手机依赖呈显著正相关（r = 0.42, p < 0.01），社交焦虑与反刍思维呈显著正相关（r = 0.38, p < 0.01），反刍思维与手机依赖亦呈显著正相关（r = 0.35, p < 0.01）。性别与手机依赖的相关不显著（r = 0.06, p > 0.05）。\", \"index\": 14, \"paraId\": \"p_muh5ej113uz3\", \"section\": \"4 结果\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"为检验反刍思维在社交焦虑与手机依赖之间的中介效应，采用PROCESS宏程序Model 4进行中介效应分析。在控制性别和年龄后，社交焦虑对手机依赖的总效应显著（β = 0.41, t = 6.23, p < 0.001）。纳入反刍思维后，社交焦虑对反刍思维的正向预测作用显著（β = 0.37, t = 5.84, p < 0.001），反刍思维对手机依赖的正向预测作用亦显著（β = 0.29, t = 4.76, p < 0.001），而社交焦虑对手机依赖的直接效应仍显著（β = 0.28, t = 4.12, p < 0.001）。Bootstrap检验（5000次抽样）表明，反刍思维的中介效应值为0.11，95%置信区间为[0.06, 0.17]，不包含0，说明中介效应显著，且中介效应占总效应的26.83%。\", \"index\": 15, \"paraId\": \"p_muh5ej11rinj\", \"section\": \"4 结果\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"进一步采用PROCESS宏程序Model 7检验性别对中介路径的调节作用。结果表明，性别对“社交焦虑→反刍思维”这一路径的调节效应显著（β = 0.15, t = 2.31, p < 0.05）。简单斜率分析显示，在男性群体中，社交焦虑对反刍思维的正向预测作用较强（β = 0.45, t = 5.12, p < 0.001）；在女性群体中，该预测作用相对较弱（β = 0.24, t = 3.08, p < 0.01）。性别对“反刍思维→手机依赖”路径的调节效应不显著（β = 0.07, t = 1.12, p > 0.05）。因此，性别调节了中介模型的前半路径，即存在有调节的中介效应。\", \"index\": 16, \"paraId\": \"p_muh5ej11itxp\", \"section\": \"4 结果\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"本研究基于社交焦虑的认知行为模型与手机依赖的补偿性使用理论，构建了一个有调节的中介模型，旨在考察社交焦虑与手机依赖之间的关系及其内在机制。研究结果表明，社交焦虑能够显著正向预测手机依赖，这一发现与既往研究一致，支持了社交焦虑个体倾向于通过手机使用来缓解现实社交中的不适感这一观点。中介分析显示，负面评价恐惧在社交焦虑与手机依赖之间起到了部分中介作用，即社交焦虑不仅直接作用于手机依赖，还通过增强个体对他人负面评价的担忧，间接促使手机依赖行为的增加。这一结果提示，社交焦虑个体对负面评价的过度关注可能是其转向手机虚拟社交的重要心理动因。\", \"index\": 17, \"paraId\": \"p_muh4xfh5r101\", \"section\": \"5 讨论\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"此外，本研究还发现，孤独感对上述中介路径的后半段具有调节作用。具体而言，当个体孤独感水平较高时，负面评价恐惧对手机依赖的正向预测作用更为显著；而当孤独感水平较低时，这一预测作用相对减弱。这表明，孤独感可能放大了负面评价恐惧对手机依赖的影响，高孤独感的社交焦虑个体更容易陷入手机依赖。该调节效应进一步揭示了社交焦虑影响手机依赖的边界条件，即个体的人际情感状态在其中扮演了重要角色。综合来看，本研究的结果有助于深化对社交焦虑与手机依赖之间复杂关系的理解，并为针对社交焦虑个体的手机依赖干预提供了理论依据，提示在干预中可同时关注负面评价恐惧与孤独感的评估与调节。\", \"index\": 18, \"paraId\": \"p_muh4xfh5gme2\", \"section\": \"5 讨论\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}], \"autoSavedAt\": \"2026-09-26T07:42:29.417Z\", \"inTextStyle\": \"(作者, 年份)\", \"projectTitle\": \"社交焦虑与手机依赖的关系研究：一个有调节的中介模型\", \"aiSuggestions\": [{\"text\": \"在 1.2 补充研究假设 H1–H3 的推导。\", \"adopted\": false, \"suggestionId\": \"sg_1\"}, {\"text\": \"讨论部分建议增加与本土研究的对话。\", \"adopted\": false, \"suggestionId\": \"sg_2\"}], \"citationStyle\": \"APA7\", \"targetJournal\": {\"name\": \"Computers in Human Behavior\", \"style\": \"APA 7\"}, \"currentSection\": \"4 结果\", \"rewriteActions\": [\"重写\", \"缩写\", \"扩写\", \"学术化改写\"], \"editorCitations\": [{\"year\": \"2024\", \"index\": 1, \"title\": \"Problematic smartphone use and social anxiety\", \"journal\": \"Computers in Human Behavior\"}, {\"year\": \"2023\", \"index\": 2, \"title\": \"Loneliness as a mediator\", \"journal\": \"Journal of Affective Disorders\"}], \"aiPolicyReminder\": {\"text\": \"该期刊要求披露 AI 使用范围，允许语言润色，禁止 AI 作者。\", \"journal\": \"Computers in Human Behavior\", \"syncedAt\": \"2026-09-25T10:24:50.452Z\"}, \"submissionChecklist\": {\"done\": 3, \"items\": [{\"text\": \"格式符合目标期刊要求（结构 / 字数 / 图表）\", \"passed\": true, \"checkId\": \"ck_format\", \"pendingText\": \"\"}, {\"text\": \"参考文献格式统一且与正文引用一致\", \"passed\": true, \"checkId\": \"ck_citation\", \"pendingText\": \"\"}, {\"text\": \"含伦理审查与知情同意声明\", \"passed\": false, \"checkId\": \"ck_ethic\", \"pendingText\": \"伦理声明待补\"}, {\"text\": \"提供数据可用性声明与可复现代码\", \"passed\": true, \"checkId\": \"ck_dataAvail\", \"pendingText\": \"\"}, {\"text\": \"按期刊政策完成 AI 使用披露\", \"passed\": false, \"checkId\": \"ck_aiDisclose\", \"pendingText\": \"AI 披露段落待补\"}], \"total\": 5}}'),('cmugtdrv2002fznwje57cgtkd','p_2002','{\"mode\": \"aiAssist\", \"stats\": {\"wordCount\": 4820, \"lastEditedAt\": \"2026-09-25T16:23:57.719Z\", \"citationCount\": 2, \"aiLabelEnabled\": true, \"paragraphCount\": 3, \"unsavedChanges\": 0}, \"title\": \"短视频使用对大学生睡眠质量的影响：基于 ESM 的实证研究\", \"editor\": {\"zoom\": 100, \"fontName\": \"Times New Roman\", \"pageCount\": 12, \"inTextLabel\": \"(作者, 年份)\", \"fontSizeLabel\": \"12pt\", \"journalFormat\": \"Computers in Human Behavior（APA 7）\", \"lineHeightLabel\": \"1.5\", \"citationStyleLabel\": \"APA 7\", \"journalFormatOptions\": [\"Computers in Human Behavior\", \"Cyberpsychology, Behavior, and Social Networking\", \"Journal of Affective Disorders\", \"心理学报（Acta Psychologica Sinica）\"]}, \"kbDocs\": [{\"title\": \"Problematic smartphone use and social anxiety\", \"paperId\": \"pa_1\", \"metaText\": \"Zhou et al. · 2024\"}, {\"title\": \"Loneliness as a mediator\", \"paperId\": \"pa_2\", \"metaText\": \"Elhai et al. · 2023\"}], \"zotero\": {\"bound\": false, \"account\": \"\", \"fallbackText\": \"未绑定时可手动导入 .bib 文件\", \"rateLimitText\": \"Zotero API 限流：每分钟 60 次\", \"bidirectionalSync\": false}, \"outline\": [{\"level\": 1, \"title\": \"1 引言\", \"nodeId\": \"o1\", \"children\": [{\"level\": 2, \"title\": \"1.1 研究背景\", \"nodeId\": \"o1_1\", \"citeCount\": 6}, {\"level\": 2, \"title\": \"1.2 问题提出\", \"nodeId\": \"o1_2\", \"citeCount\": 4}]}, {\"level\": 1, \"title\": \"2 文献综述\", \"nodeId\": \"o2\", \"children\": [{\"level\": 2, \"title\": \"2.1 社交焦虑与手机依赖\", \"nodeId\": \"o2_1\", \"citeCount\": 8}, {\"level\": 2, \"title\": \"2.2 孤独感的中介作用\", \"nodeId\": \"o2_2\", \"citeCount\": 5}, {\"level\": 2, \"title\": \"2.3 自控力的调节作用\", \"nodeId\": \"o2_3\", \"citeCount\": 3}]}, {\"flag\": \"boundArtifact\", \"level\": 1, \"title\": \"3 研究方法\", \"nodeId\": \"o3\", \"children\": [{\"level\": 2, \"title\": \"3.1 被试与程序\", \"nodeId\": \"o3_1\"}, {\"level\": 2, \"title\": \"3.2 测量工具\", \"nodeId\": \"o3_2\"}, {\"flag\": \"boundArtifact\", \"level\": 2, \"title\": \"3.3 统计策略\", \"nodeId\": \"o3_3\"}]}, {\"flag\": \"missingCitation\", \"level\": 1, \"title\": \"4 结果\", \"nodeId\": \"o4\", \"children\": []}, {\"level\": 1, \"title\": \"5 讨论\", \"nodeId\": \"o5\", \"children\": []}], \"citations\": [{\"index\": 1, \"gbText\": \"Zhou L, Wang Y, Chen H. Problematic smartphone use and social anxiety[J]. Computers in Human Behavior, 2024, 152: 108012.\", \"apaText\": \"Zhou, L., Wang, Y., & Chen, H. (2024). Problematic smartphone use and social anxiety. Computers in Human Behavior, 152, 108012.\", \"paperId\": \"pa_1\"}, {\"index\": 2, \"gbText\": \"Elhai J D, Levine J C, Hall B J. Loneliness as a mediator[J]. Journal of Affective Disorders, 2023, 331: 55-62.\", \"apaText\": \"Elhai, J. D., Levine, J. C., & Hall, B. J. (2023). Loneliness as a mediator. Journal of Affective Disorders, 331, 55–62.\", \"paperId\": \"pa_2\"}], \"authorLine\": \"陈某某 · 心理学系\", \"editorBody\": [{\"kind\": \"heading\", \"text\": \"1 引言\", \"paraId\": \"e1\"}, {\"kind\": \"body\", \"text\": \"随着智能手机的普及，手机依赖已成为影响大学生心理健康的重要风险因素\", \"paraId\": \"e2\", \"citeIndex\": 1}, {\"kind\": \"aiLabel\", \"text\": \"AI 生成 · 已核对 3 条引用\", \"paraId\": \"e3\"}, {\"kind\": \"body\", \"text\": \"既有研究表明，社交焦虑与手机依赖之间存在稳定的正相关\", \"paraId\": \"e4\", \"citeIndex\": 2}], \"kbDocCount\": 2, \"paragraphs\": [{\"kind\": \"normal\", \"text\": \"随着智能手机的普及，手机依赖已成为影响大学生心理健康的重要风险因素。\", \"index\": 1, \"paraId\": \"p1\", \"section\": \"1.1 研究背景\", \"traceLabel\": \"\", \"aiGenerated\": false}, {\"kind\": \"normal\", \"text\": \"既有研究表明，社交焦虑与手机依赖之间存在稳定的正相关，但其内在机制尚不清晰。\", \"index\": 2, \"paraId\": \"p2\", \"section\": \"1.1 研究背景\", \"traceLabel\": \"AI 生成 · 已核对 3 条引用\", \"aiGenerated\": true}, {\"kind\": \"boundMethod\", \"text\": \"本研究采用分层回归与 Bootstrap 中介检验（5000 次重抽样），所有分析在沙箱中完成并可复现。\", \"index\": 3, \"paraId\": \"p3\", \"section\": \"3.3 统计策略\", \"traceLabel\": \"绑定分析产物 · run_2024\", \"aiGenerated\": true}], \"autoSavedAt\": \"2026-09-25T16:23:57.719Z\", \"inTextStyle\": \"(作者, 年份)\", \"projectTitle\": \"短视频使用对大学生睡眠质量的影响：基于 ESM 的实证研究\", \"aiSuggestions\": [{\"text\": \"在 1.2 补充研究假设 H1–H3 的推导。\", \"adopted\": false, \"suggestionId\": \"sg_1\"}, {\"text\": \"讨论部分建议增加与本土研究的对话。\", \"adopted\": false, \"suggestionId\": \"sg_2\"}], \"citationStyle\": \"APA7\", \"targetJournal\": {\"name\": \"Computers in Human Behavior\", \"style\": \"APA 7\"}, \"currentSection\": \"1.1 研究背景\", \"rewriteActions\": [\"重写\", \"缩写\", \"扩写\", \"学术化改写\"], \"editorCitations\": [{\"year\": \"2024\", \"index\": 1, \"title\": \"Problematic smartphone use and social anxiety\", \"journal\": \"Computers in Human Behavior\"}, {\"year\": \"2023\", \"index\": 2, \"title\": \"Loneliness as a mediator\", \"journal\": \"Journal of Affective Disorders\"}], \"aiPolicyReminder\": {\"text\": \"该期刊要求披露 AI 使用范围，允许语言润色，禁止 AI 作者。\", \"journal\": \"Computers in Human Behavior\", \"syncedAt\": \"2026-09-25T10:24:50.494Z\"}, \"submissionChecklist\": {\"done\": 3, \"items\": [{\"text\": \"格式符合目标期刊要求（结构 / 字数 / 图表）\", \"passed\": true, \"checkId\": \"ck_format\", \"pendingText\": \"\"}, {\"text\": \"参考文献格式统一且与正文引用一致\", \"passed\": true, \"checkId\": \"ck_citation\", \"pendingText\": \"\"}, {\"text\": \"含伦理审查与知情同意声明\", \"passed\": false, \"checkId\": \"ck_ethic\", \"pendingText\": \"伦理声明待补\"}, {\"text\": \"提供数据可用性声明与可复现代码\", \"passed\": true, \"checkId\": \"ck_dataAvail\", \"pendingText\": \"\"}, {\"text\": \"按期刊政策完成 AI 使用披露\", \"passed\": false, \"checkId\": \"ck_aiDisclose\", \"pendingText\": \"AI 披露段落待补\"}], \"total\": 5}}'),('cmugtdrvw003fznwjw2mrgsuo','p_2003','{\"mode\": \"aiFull\", \"stats\": {\"wordCount\": 5, \"lastEditedAt\": \"2026-09-25T17:01:24.330Z\", \"citationCount\": 2, \"aiLabelEnabled\": true, \"paragraphCount\": 20, \"unsavedChanges\": 0}, \"title\": \"导师制对研究生科研效能的影响：一项追踪研究设计\", \"editor\": {\"zoom\": 100, \"fontName\": \"Times New Roman\", \"pageCount\": 12, \"inTextLabel\": \"(作者, 年份)\", \"fontSizeLabel\": \"12pt\", \"journalFormat\": \"Computers in Human Behavior（APA 7）\", \"lineHeightLabel\": \"1.5\", \"citationStyleLabel\": \"APA 7\", \"journalFormatOptions\": [\"Computers in Human Behavior\", \"Cyberpsychology, Behavior, and Social Networking\", \"Journal of Affective Disorders\", \"心理学报（Acta Psychologica Sinica）\"]}, \"kbDocs\": [{\"title\": \"Problematic smartphone use and social anxiety\", \"paperId\": \"pa_1\", \"metaText\": \"Zhou et al. · 2024\"}, {\"title\": \"Loneliness as a mediator\", \"paperId\": \"pa_2\", \"metaText\": \"Elhai et al. · 2023\"}], \"zotero\": {\"bound\": false, \"account\": \"\", \"fallbackText\": \"未绑定时可手动导入 .bib 文件\", \"rateLimitText\": \"Zotero API 限流：每分钟 60 次\", \"bidirectionalSync\": false}, \"outline\": [{\"level\": 1, \"title\": \"1 引言\", \"nodeId\": \"o1\", \"children\": [{\"level\": 2, \"title\": \"1.1 研究背景\", \"nodeId\": \"o1_1\", \"citeCount\": 6}, {\"level\": 2, \"title\": \"1.2 问题提出\", \"nodeId\": \"o1_2\", \"citeCount\": 4}]}, {\"level\": 1, \"title\": \"2 文献综述\", \"nodeId\": \"o2\", \"children\": [{\"level\": 2, \"title\": \"2.1 社交焦虑与手机依赖\", \"nodeId\": \"o2_1\", \"citeCount\": 8}, {\"level\": 2, \"title\": \"2.2 孤独感的中介作用\", \"nodeId\": \"o2_2\", \"citeCount\": 5}, {\"level\": 2, \"title\": \"2.3 自控力的调节作用\", \"nodeId\": \"o2_3\", \"citeCount\": 3}]}, {\"flag\": \"boundArtifact\", \"level\": 1, \"title\": \"3 研究方法\", \"nodeId\": \"o3\", \"children\": [{\"level\": 2, \"title\": \"3.1 被试与程序\", \"nodeId\": \"o3_1\"}, {\"level\": 2, \"title\": \"3.2 测量工具\", \"nodeId\": \"o3_2\"}, {\"flag\": \"boundArtifact\", \"level\": 2, \"title\": \"3.3 统计策略\", \"nodeId\": \"o3_3\"}]}, {\"flag\": \"missingCitation\", \"level\": 1, \"title\": \"4 结果\", \"nodeId\": \"o4\", \"children\": []}, {\"level\": 1, \"title\": \"5 讨论\", \"nodeId\": \"o5\", \"children\": []}], \"citations\": [{\"index\": 1, \"gbText\": \"Zhou L, Wang Y, Chen H. Problematic smartphone use and social anxiety[J]. Computers in Human Behavior, 2024, 152: 108012.\", \"apaText\": \"Zhou, L., Wang, Y., & Chen, H. (2024). Problematic smartphone use and social anxiety. Computers in Human Behavior, 152, 108012.\", \"paperId\": \"pa_1\"}, {\"index\": 2, \"gbText\": \"Elhai J D, Levine J C, Hall B J. Loneliness as a mediator[J]. Journal of Affective Disorders, 2023, 331: 55-62.\", \"apaText\": \"Elhai, J. D., Levine, J. C., & Hall, B. J. (2023). Loneliness as a mediator. Journal of Affective Disorders, 331, 55–62.\", \"paperId\": \"pa_2\"}], \"authorLine\": \"陈某某 · 心理学系\", \"editorBody\": [{\"kind\": \"heading\", \"text\": \"1 引言\", \"paraId\": \"e1\"}, {\"kind\": \"body\", \"text\": \"随着智能手机的普及，手机依赖已成为影响大学生心理健康的重要风险因素\", \"paraId\": \"e2\", \"citeIndex\": 1}, {\"kind\": \"aiLabel\", \"text\": \"AI 生成 · 已核对 3 条引用\", \"paraId\": \"e3\"}, {\"kind\": \"body\", \"text\": \"既有研究表明，社交焦虑与手机依赖之间存在稳定的正相关\", \"paraId\": \"e4\", \"citeIndex\": 2}], \"kbDocCount\": 2, \"paragraphs\": [{\"kind\": \"normal\", \"text\": \"随着智能手机的普及，手机依赖已成为影响大学生心理健康的重要风险因素。\", \"index\": 1, \"paraId\": \"p1\", \"section\": \"1.1 研究背景\", \"traceLabel\": \"\", \"aiGenerated\": false}, {\"kind\": \"normal\", \"text\": \"已有研究结果显示，社交焦虑与手机依赖之间呈现出一种稳定的正相关关系。具体而言，这种正相关关系意味着，社交焦虑水平较高的个体，往往也更容易表现出较高程度的手机依赖；反之，社交焦虑水平较低的个体，其手机依赖程度通常也相对较低。然而，尽管这种关联在已有研究中表现出一定的稳定性，但对于这种关联背后的内在机制，目前仍缺乏清晰的认识。\", \"index\": 2, \"paraId\": \"p2\", \"section\": \"1.1 研究背景\", \"traceLabel\": \"AI 改写\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"研究生教育是培养高层次创新人才的主要途径，科研效能则是衡量研究生培养质量的关键指标之一。导师作为研究生培养的第一责任人，其指导方式、指导频率与指导质量对研究生的科研能力发展具有重要影响。然而，现有研究多采用横截面设计，难以揭示导师制与研究生科研效能之间的动态关系及因果方向。\", \"index\": 3, \"paraId\": \"p_muh7hkbn3vp1\", \"section\": \"1.2 问题提出\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"已有文献虽已关注导师指导行为与研究生科研产出、科研自我效能感之间的关联，但多数研究在单一时间点收集数据，无法区分“导师指导促进科研效能提升”与“科研效能较高的研究生更易获得有效指导”这两种可能。同时，导师制作为一个多维构念，其不同维度（如学术支持、情感支持、自主性支持）对科研效能的影响是否随时间变化，尚缺乏系统的追踪证据。\", \"index\": 4, \"paraId\": \"p_muh7hkbnnaxy\", \"section\": \"1.2 问题提出\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"基于此，本研究拟采用追踪研究设计，在多个时间点收集数据，考察导师制对研究生科研效能的影响及其动态变化过程，以期为优化导师指导实践、提升研究生培养质量提供实证依据。\", \"index\": 5, \"paraId\": \"p_muh7hkbnzse8\", \"section\": \"1.2 问题提出\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"社交焦虑与手机依赖之间的关系是理解研究生心理适应与行为模式的重要切入点。社交焦虑通常指个体在社交情境中体验到的显著恐惧或担忧，担心自己的行为或表现会受到他人的负面评价。手机依赖则指个体对智能手机使用失去控制，并因此产生一系列负面后果的行为模式。已有研究提示，社交焦虑水平较高的个体可能更倾向于通过手机使用来缓解现实社交中的不适感，从而增加手机依赖的风险。\", \"index\": 6, \"paraId\": \"p_muh7hnlury6q\", \"section\": \"2.1 社交焦虑与手机依赖\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"然而，现有研究多采用横断面设计，难以明确社交焦虑与手机依赖之间的时序关系与因果方向。社交焦虑可能先于手机依赖出现，也可能与手机依赖形成相互强化的循环。此外，研究生群体面临独特的学术与社交压力，其社交焦虑与手机依赖的表现可能与本科生或其他群体有所不同。因此，有必要通过追踪研究设计，考察社交焦虑与手机依赖在研究生群体中的动态关联，并进一步探讨导师制是否可能在这一关系中发挥调节或缓冲作用。\", \"index\": 7, \"paraId\": \"p_muh7hnlulwgb\", \"section\": \"2.1 社交焦虑与手机依赖\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"在探讨导师制对研究生科研效能的影响机制时，孤独感被视为一个潜在的中介变量。研究生阶段的科研活动通常具有较高的自主性与独立性，个体与导师、同伴之间的互动频率和深度可能影响其孤独感体验。既有研究表明，孤独感与个体的心理健康、学业投入及科研表现存在关联，但针对研究生群体中导师制通过孤独感影响科研效能的路径尚需进一步检验。\", \"index\": 8, \"paraId\": \"p_muh7hqfa86c0\", \"section\": \"2.2 孤独感的中介作用\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"基于上述分析，本研究拟采用追踪设计，考察孤独感在导师制与研究生科研效能之间所可能发挥的中介作用。具体而言，本研究将检验导师制的不同维度（如指导频率、指导质量、情感支持等）是否通过改变研究生的孤独感水平，进而影响其科研效能。追踪数据所具有的时序特征有助于增强对中介效应因果方向的推断，但研究结论仍需结合理论框架与实证结果审慎得出。\\n\\n在具体操作层面，本研究将分阶段采集数据，以清晰呈现导师制各维度、孤独感与科研效能之间的动态关联。通过交叉滞后分析等统计方法，可以初步检验变量间的时序先后关系，从而为中介效应的因果推断提供更为稳健的经验依据。然而，由于追踪研究仍可能受到共同方法偏差、样本流失及未观测变量等问题的干扰，对结果的解释必须保持谨慎。因此，本研究将在理论框架的指导下，结合实证结果进行综合讨论，避免过度因果化解读，以确保结论的严谨性与可靠性。\", \"index\": 9, \"paraId\": \"p_muh7hqfa72nn\", \"section\": \"2.2 孤独感的中介作用\", \"traceLabel\": \"AI 改写\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"自控力作为个体自我调节能力的核心成分，指个体有意识地控制冲动、调节情绪与行为以服务于长期目标的能力。在研究生教育情境中，自控力可能影响学生如何分配时间、应对科研挫折以及坚持完成阶段性任务。已有研究表明，自控力与学业拖延、学业投入等变量存在关联，但其在导师制与科研效能关系中的角色尚需进一步检验。\", \"index\": 10, \"paraId\": \"p_muh7immyznb8\", \"section\": \"2.3 自控力的调节作用\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"基于调节效应的分析框架，本研究提出如下假设：导师制对研究生科研效能的影响可能因个体自控力水平的不同而存在差异。具体而言，对于自控力较高的研究生，导师所提供的指导与支持可能更易于转化为持续的科研投入，并进而促进科研效能的提升；而对于自控力较低的研究生，同样的导师指导可能因执行意图不足或拖延倾向而效果减弱。为检验这一假设，本研究将在追踪设计中使用交互项检验予以考察，以明确自控力是否构成导师制发挥作用的边界条件。\", \"index\": 11, \"paraId\": \"p_muh7immy19wv\", \"section\": \"2.3 自控力的调节作用\", \"traceLabel\": \"AI 改写\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"本研究采用追踪研究设计，旨在考察导师制对研究生科研效能的影响。被试为来自某综合性大学的研究生，通过方便抽样与滚雪球抽样相结合的方式招募。纳入标准为：当前正在接受导师指导、至少完成一个学期的科研训练、且自愿参与本研究。最终样本量为N=XXX（具体人数待定），其中男性XX人，女性XX人，平均年龄XX岁（SD=XX）。被试来自不同学科门类，包括理工科、人文社科等，以增强样本的异质性。\", \"index\": 12, \"paraId\": \"p_muh7ivnoaym1\", \"section\": \"3.1 被试与程序\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"研究程序分为三个阶段，间隔均为6个月。第一阶段（T1）在学期初进行，被试完成基本信息问卷、导师制感知量表与科研效能感量表。第二阶段（T2）在6个月后，重复测量导师制感知与科研效能感，并增加科研投入与导师支持行为等过程变量。第三阶段（T3）在12个月后，再次测量核心变量，并收集科研产出（如论文发表、会议报告）等结果指标。每次测量均通过线上问卷平台发放，被试签署知情同意书，并给予适量报酬。所有数据仅用于研究目的，严格保密。\", \"index\": 13, \"paraId\": \"p_muh7ivnodi8n\", \"section\": \"3.1 被试与程序\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"本研究采用多源、多时点的测量策略，以降低共同方法偏差并捕捉导师制与研究生科研效能的动态变化。导师制测量工具在参考国内外相关量表的基础上，结合我国研究生教育情境进行改编，涵盖指导频率、指导内容、指导关系质量等维度。科研效能测量工具则聚焦于研究生在文献阅读、研究设计、数据分析、论文撰写与学术交流等科研任务中的自我效能感。所有量表均采用Likert五点计分，从“完全不符合”到“完全符合”。\", \"index\": 14, \"paraId\": \"p_muh7izdy9631\", \"section\": \"3.2 测量工具\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"在正式施测前，将邀请相关领域专家对量表的内容效度进行评定，并通过预测试检验量表的信度与结构效度。追踪研究设计包含三个时间点，每个时间点均测量导师制与科研效能，以考察二者之间的纵向关系。此外，还将收集研究生的性别、年级、学科门类等人口学与背景信息，作为控制变量纳入分析。\", \"index\": 15, \"paraId\": \"p_muh7izdy2nsb\", \"section\": \"3.2 测量工具\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"boundMethod\", \"text\": \"本研究采用分层回归与 Bootstrap 中介检验（5000 次重抽样），所有分析在沙箱中完成并可复现。\", \"index\": 16, \"paraId\": \"p3\", \"section\": \"3.3 统计策略\", \"traceLabel\": \"绑定分析产物 · run_2024\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"本研究采用追踪设计，对参与导师制的研究生进行多时间点数据收集。初步分析显示，导师制与研究生科研效能之间存在正向关联，但具体效应量及因果关系需进一步通过纵向模型检验。\", \"index\": 17, \"paraId\": \"p_muh7j6pqt9ss\", \"section\": \"4 结果\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"在控制基线科研效能后，导师制指导频率与质量对后续科研效能变化的预测作用尚在分析中。后续将报告结构方程模型及多层线性模型结果，以揭示导师制影响科研效能的动态过程。\", \"index\": 18, \"paraId\": \"p_muh7j6pq8kr4\", \"section\": \"4 结果\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"本研究采用追踪设计，考察了导师制对研究生科研效能的影响。基于多时间点的数据，我们得以观察科研效能在导师指导过程中的动态变化，并初步检验导师支持行为与研究生科研效能之间的纵向关联。与横断面研究相比，这一设计有助于减少个体间稳定差异带来的混淆，为理解导师制的作用提供了更为可靠的时序证据。\", \"index\": 19, \"paraId\": \"p_muh7ja4jyz7p\", \"section\": \"5 讨论\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}, {\"kind\": \"normal\", \"text\": \"需要指出的是，本研究的结果应谨慎解读。追踪设计虽然能够揭示变量随时间变化的共变模式，但并不能直接确立因果关系。科研效能的提升可能受到多种因素共同作用，例如研究生自身的投入、课题组氛围以及学科差异等，这些因素在本研究中未能完全控制。此外，样本的流失和测量工具的信效度也可能对结果产生一定影响。未来研究可结合质性访谈或干预实验，进一步探讨导师制影响科研效能的具体机制与边界条件。\", \"index\": 20, \"paraId\": \"p_muh7ja4jj9pq\", \"section\": \"5 讨论\", \"traceLabel\": \"AI 生成\", \"aiGenerated\": true}], \"autoSavedAt\": \"2026-09-25T17:01:24.330Z\", \"inTextStyle\": \"(作者, 年份)\", \"projectTitle\": \"导师制对研究生科研效能的影响：一项追踪研究设计\", \"aiSuggestions\": [{\"text\": \"在 1.2 补充研究假设 H1–H3 的推导。\", \"adopted\": false, \"suggestionId\": \"sg_1\"}, {\"text\": \"讨论部分建议增加与本土研究的对话。\", \"adopted\": false, \"suggestionId\": \"sg_2\"}], \"citationStyle\": \"APA7\", \"targetJournal\": {\"name\": \"Computers in Human Behavior\", \"style\": \"APA 7\"}, \"currentSection\": \"5 讨论\", \"rewriteActions\": [\"重写\", \"缩写\", \"扩写\", \"学术化改写\"], \"editorCitations\": [{\"year\": \"2024\", \"index\": 1, \"title\": \"Problematic smartphone use and social anxiety\", \"journal\": \"Computers in Human Behavior\"}, {\"year\": \"2023\", \"index\": 2, \"title\": \"Loneliness as a mediator\", \"journal\": \"Journal of Affective Disorders\"}], \"aiPolicyReminder\": {\"